%dw 2.0 output application/json
var billingData= vars.billingResponsePayload var escrow=vars.billingResponsePayload.primaryAccount.policies
fun mapEscrow(isEscrow)= isEscrow map ((item, index) -> { "policyNumber": item.policyNumber, "hasEscrow": item.policyTerm.escrowAccount?, "billingStatus": if (item.policyTerm is Array) item.policyTerm[sizeOf(item.policyTerm) - 1].status else item.policyTerm.status }) //formatting, to get numbers properly formatted to #.## takes a bit of mumbo jumbo // as Number as String {format:"0.00"} as Number fun mapbillTocontact(billTocontact)=( { "name": billTocontact.name, "address":{ "street": billTocontact.addressLine1, "city":billTocontact.city, "state":billTocontact.state, "zip": billTocontact.zip }
} ) --- { "accountBalance": billingData.primaryAccount.accountBalance as Number as String {format:"0.00"} as Number default null, "accountNumber": billingData.primaryAccount.accountNumber, "billTocontact": mapbillTocontact(billingData.primaryAccount.billTocontact), "billingSystemCode":billingData.primaryAccount.billingSystemCode, "billType":billingData.primaryAccount.billType, "dueAmount":billingData.primaryAccount.currentAmountDue as Number as String {format: "0.00"} as Number default null, "dueDate":billingData.primaryAccount.currentAmountDueDate , "dateBilled":billingData.primaryAccount.dateBilled, "lastPaymentAmount":billingData.primaryAccount.lastPaymentReceived as Number as String {format: "0.00"} as Number default null, "lastPaymentDate":billingData.primaryAccount.lastPaymentReceivedDate, "eft":billingData.primaryAccount.eftEstablished, "pastDueAmount":billingData.primaryAccount.pastDueAmount as Number as String {format: "0.00"} as Number default null, "pastDueDate":billingData.primaryAccount.pastDueDate, "policies": if(typeOf(escrow) matches "Object") mapEscrow([escrow]) else mapEscrow(escrow) }

